BEGIN;
SELECT no_plan();

INSERT INTO auth.users(id,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,aud,role,created_at,updated_at)
VALUES('e1000000-0000-4000-8000-000000000001','halfday-manager@example.test','hash',now(),'{}','{}','authenticated','authenticated',now(),now());
INSERT INTO platform_core.tenants(id,display_name,created_by_operator_id) VALUES('e1100000-0000-4000-8000-000000000001','Halfday mapping test','e1000000-0000-4000-8000-000000000001');
INSERT INTO platform_core.tenant_roles(tenant_id,role_id,role_key,role_version,permission_snapshot,protects_tenant_admin)
VALUES('e1100000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','attendance.policy.manager.v1',1,ARRAY['attendance_policy.manage','people.view','people.manage','employment.manage','compensation.manage','org_context.manage'],false);
INSERT INTO platform_core.tenant_memberships(tenant_id,user_id,access_state,created_by_operator_id)
VALUES('e1100000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','active','e1000000-0000-4000-8000-000000000001');
INSERT INTO platform_core.membership_roles(tenant_id,user_id,role_id)
VALUES('e1100000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001');
INSERT INTO platform_core.tenant_capability_entitlements(tenant_id,capability_key,is_granted,valid_from,actor_user_id,reason)
VALUES('e1100000-0000-4000-8000-000000000001','hr.attendance',true,now()-interval '1 minute','e1000000-0000-4000-8000-000000000001','halfday config test');

SELECT ok(to_regprocedure('public.save_time_work_policy(uuid,uuid,text,text,text,text,smallint[],time,time,boolean,integer,integer,time,time,integer,integer,boolean,integer,integer,boolean)') IS NOT NULL,'legacy save RPC keeps its exact full identity signature');
SELECT ok(has_function_privilege('authenticated','public.save_time_work_policy_with_leave_mapping(uuid,uuid,text,text,text,text,smallint[],time,time,boolean,integer,integer,time,time,integer,integer,boolean,integer,integer,boolean,time,time,integer)','EXECUTE'),'authorized client can call the explicitly versioned mapping RPC');
SELECT ok(NOT has_function_privilege('anon','public.save_time_work_policy_with_leave_mapping(uuid,uuid,text,text,text,text,smallint[],time,time,boolean,integer,integer,time,time,integer,integer,boolean,integer,integer,boolean,time,time,integer)','EXECUTE'),'anonymous caller cannot configure policy mapping');
SELECT ok(NOT has_function_privilege('authenticated','time.leave_halfday_mapping(jsonb,date,text)','EXECUTE'),'calculator remains private');

SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000001',true);
SELECT set_config('test.fixed',public.save_time_work_policy_with_leave_mapping('e1100000-0000-4000-8000-000000000001',NULL,'FIX','Fixed mapped','fixed','Africa/Cairo',ARRAY[1,2,3,4,5]::smallint[],'09:00','17:00',false,60,NULL,NULL,NULL,120,360,false,30,15,false,'13:00','14:00',NULL)::text,true);
SELECT set_config('test.fixed_id',current_setting('test.fixed')::jsonb->>'id',true);
SELECT is((current_setting('test.fixed')::jsonb->>'version')::integer,1,'mapping-aware save writes first version');
SELECT is((SELECT item->>'fixed_break_start' FROM jsonb_array_elements(public.time_work_policy_catalog('e1100000-0000-4000-8000-000000000001')->'items') AS items(item) WHERE item->>'code'='FIX'),'13:00:00','catalog exposes fixed placement on the immutable head version');
SELECT throws_ok($$SELECT public.save_time_work_policy_with_leave_mapping('e1100000-0000-4000-8000-000000000001',current_setting('test.fixed_id')::uuid,'FIX','Invalid break','fixed','Africa/Cairo',ARRAY[1,2,3,4,5]::smallint[],'09:00','17:00',false,60,NULL,NULL,NULL,120,360,false,30,15,false,'13:00','13:30',NULL)$$,'22023','time_policy_halfday_mapping_invalid','configured fixed break length must match aggregate break');
SELECT set_config('test.flex',public.save_time_work_policy_with_leave_mapping('e1100000-0000-4000-8000-000000000001',NULL,'FLEX','Flexible mapped','flexible','Africa/Cairo',ARRAY[1,2,3,4,5]::smallint[],NULL,NULL,false,30,481,'07:00','11:00',120,360,false,30,15,false,NULL,NULL,12)::text,true);
SELECT is(((SELECT item->>'flexible_halfday_break_minutes' FROM jsonb_array_elements(public.time_work_policy_catalog('e1100000-0000-4000-8000-000000000001')->'items') AS items(item) WHERE item->>'code'='FLEX'))::integer,12,'flexible halfday break is explicitly stored on its new version');
SELECT throws_ok($$SELECT public.save_time_work_policy_with_leave_mapping('e1100000-0000-4000-8000-000000000001',NULL,'BADFLEX','Missing flex mapping','flexible','Africa/Cairo',ARRAY[1]::smallint[],NULL,NULL,false,30,481,'07:00','11:00',120,360,false,30,15,false,NULL,NULL,NULL)$$,'22023','time_policy_halfday_mapping_invalid','mapping-aware flexible save requires explicit halfday break minutes');
-- Legacy caller shape remains valid and stores unknown mapping rather than guessing from aggregate break.
SELECT set_config('test.legacy',public.save_time_work_policy('e1100000-0000-4000-8000-000000000001',NULL,'LEGACY','Legacy unknown','fixed','Africa/Cairo',ARRAY[1,2,3,4,5]::smallint[],'09:00','17:00',false,45,NULL,NULL,NULL,120,360,false,30,15,false)::text,true);
SELECT ok((SELECT item->>'fixed_break_start' FROM jsonb_array_elements(public.time_work_policy_catalog('e1100000-0000-4000-8000-000000000001')->'items') AS items(item) WHERE item->>'code'='LEGACY') IS NULL,'legacy save does not infer a break placement');
SELECT set_config('test.legacy_zero',public.save_time_work_policy('e1100000-0000-4000-8000-000000000001',NULL,'LEGACY0','Legacy zero break','fixed','Africa/Cairo',ARRAY[1,2,3,4,5]::smallint[],'09:00','17:00',false,0,NULL,NULL,NULL,120,360,false,30,15,false)::text,true);
RESET ROLE;
SELECT throws_ok($$UPDATE time.work_policy_versions SET fixed_break_start='13:00' WHERE tenant_id='e1100000-0000-4000-8000-000000000001' AND template_id=(current_setting('test.fixed')::jsonb->>'id')::uuid AND version=1$$,'55000','time_work_policy_version_immutable','mapping fields share immutable policy-version protection');

SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_version',1),'2026-10-05','first')->>'split_local')::timestamp,timestamp '2026-10-05 12:30:00','09–17 with 13–14 break splits at 12:30');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_version',1),'2026-10-05','second')->'excused_intervals'->0->>'start_local')::timestamp,timestamp '2026-10-05 12:30:00','second part returns its first working interval from the split');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_version',1),'2026-10-05','second')->'excused_intervals'->0->>'end_local')::timestamp,timestamp '2026-10-05 13:00:00','second part stops before configured break');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_version',1),'2026-10-05','second')->'excused_intervals'->1->>'start_local')::timestamp,timestamp '2026-10-05 14:00:00','second part resumes after configured break');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_version',1),'2026-10-05','second')->'remaining_intervals'->0->>'end_local')::timestamp,timestamp '2026-10-05 12:30:00','response includes complementary excused interval too');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_version',1),'2026-10-05','second')->'break_interval'->0->>'start_local')::timestamp,timestamp '2026-10-05 13:00:00','response includes resolved configured break interval');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_template_id','d8600000-0000-4000-8000-000000000001','policy_version',7),'2026-10-05','second')->>'source_policy_version','7','response identifies source policy version');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',60,'fixed_break_start','13:00','fixed_break_end','14:00','policy_version',1),'2026-10-05','second')->'configured_policy'->>'fixed_break_start','13:00','response carries the exact configured source fields');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',45,'fixed_break_start','12:00','fixed_break_end','12:45','policy_version',1),'2026-10-05','first')->>'split_local')::timestamp,timestamp '2026-10-05 13:22:00','435 net minutes split 217/218 without rounding both halves upward');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','flexible','timezone_name','Africa/Cairo','required_minutes',481,'flexible_halfday_break_minutes',12,'policy_version',1),'2026-10-05',NULL)->>'remaining_net_threshold_minutes'),'241','flexible 481-minute requirement uses ceil-half threshold');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','flexible','timezone_name','Africa/Cairo','required_minutes',481,'policy_version',1),'2026-10-05',NULL)->>'reason','flexible_halfday_break_unknown','legacy flexible aggregate break remains review-required');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','flexible','timezone_name','not/a-zone','required_minutes',481,'flexible_halfday_break_minutes',12),'2026-10-05',NULL)->>'reason','timezone_unavailable','flexible policy validates its timezone');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','flexible','timezone_name','Africa/Cairo','required_minutes',999,'flexible_halfday_break_minutes',12),'2026-10-05',NULL)->>'reason','flexible_required_minutes_invalid','flexible policy duration bounds are checked');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',45,'policy_version',1),'2026-10-05','first')->>'reason','fixed_break_placement_unknown','legacy positive break remains review-required');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','09:00','shift_end','17:00','ends_next_day',false,'break_minutes',0,'policy_version',1),'2026-10-05','first')->>'state','mapped','legacy fixed policy with zero aggregate break needs no placement');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id',NULL,'head_version','null','schedule_kind','flexible','timezone_name','Africa/Cairo','required_minutes',481,'flexible_halfday_break_minutes',12),'2026-10-05',NULL)->>'reason','policy_identity_missing','JSON null identity cannot be treated as a source policy');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','25:00','shift_end','17:00','ends_next_day',false,'break_minutes',0,'policy_version',1),'2026-10-05','first')->>'reason','policy_snapshot_invalid','invalid datetime cast becomes review-required');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','Africa/Cairo','shift_start','22:00','shift_end','06:00','ends_next_day',true,'break_minutes',30,'fixed_break_start','02:00','fixed_break_end','02:30','policy_version',1),'2026-10-05','second')->'excused_intervals'->0->>'start_local')::timestamp,timestamp '2026-10-06 01:45:00','overnight split follows next-day break placement on operational date');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','America/New_York','shift_start','22:00','shift_end','06:00','ends_next_day',true,'break_minutes',0,'policy_version',1),'2026-03-07','second')->>'scheduled_net_minutes')::integer,420,'valid overnight DST shift splits using resolved UTC elapsed minutes');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','America/New_York','shift_start','12:00','shift_end','01:30','ends_next_day',true,'break_minutes',0,'policy_version',1),'2026-10-31','first')->>'reason','local_time_gap_or_overlap','invalid endpoint on complementary remaining interval makes the full mapping review-required');
SELECT is((time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','America/New_York','shift_start','00:00','shift_end','04:00','ends_next_day',false,'break_minutes',0,'policy_version',1),'2026-03-08','first')->>'scheduled_net_minutes')::integer,180,'valid spring DST shift uses three resolved UTC elapsed hours');
SELECT is(time.leave_halfday_mapping(jsonb_build_object('id','d8600000-0000-4000-8000-000000000001','head_version',1,'schedule_kind','fixed','timezone_name','America/New_York','shift_start','00:00','shift_end','03:00','ends_next_day',false,'break_minutes',0,'policy_version',1),'2026-11-01','first')->>'reason','local_time_gap_or_overlap','DST fall overlap uses the existing resolver and requests review');

SELECT * FROM finish();
ROLLBACK;






